"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/notification-center/variants/01-dropdown";
import Variant1 from "./components/notification-center/variants/02-panel";
const variants = {"dropdown": Variant0,"panel": Variant1};
export interface ArtemisNotificationCenterProps { className?: string; variant?: "dropdown" | "panel"; }
export function ArtemisNotificationCenter({ className, variant = "dropdown" }: ArtemisNotificationCenterProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useState } from "react";
import { FILTERS, INITIAL_ITEMS } from "./01-dropdown/data";
import { NotificationDropdown } from "./01-dropdown/notification-dropdown";
export default function NotificationCenterDropdown() {
    const [items, setItems] = useState(INITIAL_ITEMS);
    const [message, setMessage] = useState("");
    return (<div className="art:flex art:w-full art:flex-col art:items-center art:justify-start art:gap-4">
      <>

        <NotificationDropdown items={items} filters={FILTERS} onReadChange={(item, read) => setItems((current) => current.map((entry) => (entry.id === item.id ? { ...entry, read } : entry)))} onMarkAllRead={() => setItems((current) => current.map((item) => ({ ...item, read: true })))} onSnooze={(item) => {
            setItems((current) => current.filter((entry) => entry.id !== item.id));
            setMessage(`Snoozed: ${item.title}. Demo only; no reminder scheduled.`);
        }} onArchive={(item) => {
            setItems((current) => current.filter((entry) => entry.id !== item.id));
            setMessage(`Archived: ${item.title}`);
        }} onSelect={(item) => {
            setItems((current) => current.map((entry) => (entry.id === item.id ? { ...entry, read: true } : entry)));
            setMessage(`Opened: ${item.title}`);
        }}/>
      </>
      <output className="art:max-w-sm art:text-center art:text-xs art:text-muted-foreground">{message}</output>
    </div>);
}

