"use client";
// @zeus-internal
import { motion, type Transition, useReducedMotion } from "motion/react";
import { createContext, type FocusEvent, type PointerEvent, type ReactNode, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
const OPEN_DELAY = 180;
const CLOSE_DELAY = 80;
const UNMOUNT_AFTER = 432;
const GAP = 10;
const VIEWPORT_MARGIN = 12;
const TEXT_SPRING = { type: "spring", stiffness: 445, damping: 34.5, mass: 1 } as const;
const MORPH_SPRING = { type: "spring", stiffness: 215, damping: 25, mass: 1.2 } as const;
const ROOT_FADE = { duration: 0.15, ease: ARTEMIS_EASE_OUT } as const;
const TEXT_FADE = { duration: 0.14, ease: ARTEMIS_EASE_OUT } as const;
const INSTANT = { duration: 0 } as const;
type Anchor = {
    left: number;
    top: number;
    width: number;
};
type Tip = {
    id: number;
    content: ReactNode;
    anchor: Anchor;
};
type TooltipApi = {
    show: (id: number, content: ReactNode, el: HTMLElement, delay: number) => void;
    hide: (id: number, delay: number) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
let nextTriggerId = 1;
function measure(el: HTMLElement): Anchor {
    const r = el.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width };
}
export function ArtemisMorphicTooltipProvider({ children }: {
    children: ReactNode;
}) {
    const reduce = useReducedMotion();
    const [tip, setTip] = useState<Tip | null>(null);
    const [open, setOpen] = useState(false);
    const [session, setSession] = useState(0);
    const openRef = useRef(false);
    const currentId = useRef<number | null>(null);
    const timer = useRef<number | null>(null);
    const removeTimer = useRef<number | null>(null);
    const clearRemove = useCallback(() => {
        if (removeTimer.current !== null)
            window.clearTimeout(removeTimer.current);
        removeTimer.current = null;
    }, []);
    const clear = useCallback(() => {
        if (timer.current !== null)
            window.clearTimeout(timer.current);
        timer.current = null;
    }, []);
    const api = useMemo<TooltipApi>(() => ({
        show(id, content, el, delay) {
            clear();
            const reveal = () => {
                timer.current = null;
                clearRemove();
                const wasOpen = openRef.current;
                currentId.current = id;
                openRef.current = true;
                if (!wasOpen)
                    setSession((s) => s + 1);
                setTip({ id, content, anchor: measure(el) });
                setOpen(true);
                window.requestAnimationFrame(() => {
                    if (currentId.current !== id || !el.isConnected)
                        return;
                    const anchor = measure(el);
                    setTip((prev) => prev && prev.id === id && (prev.anchor.top !== anchor.top || prev.anchor.left !== anchor.left)
                        ? { ...prev, anchor }
                        : prev);
                });
            };
            if (openRef.current || delay <= 0)
                reveal();
            else
                timer.current = window.setTimeout(reveal, delay);
        },
        hide(id, delay) {
            if (currentId.current !== id && timer.current === null)
                return;
            clear();
            const close = () => {
                timer.current = null;
                if (currentId.current !== id)
                    return;
                openRef.current = false;
                currentId.current = null;
                setOpen(false);
                clearRemove();
                removeTimer.current = window.setTimeout(() => {
                    removeTimer.current = null;
                    setTip(null);
                }, UNMOUNT_AFTER);
            };
            if (!openRef.current)
                return;
            if (delay <= 0)
                close();
            else
                timer.current = window.setTimeout(close, delay);
        },
    }), [clear, clearRemove]);
    useEffect(() => () => {
        clear();
        clearRemove();
    }, [clear, clearRemove]);
    return (<TooltipContext.Provider value={api}>
      {children}
      {tip ? <TooltipLayer tip={tip} open={open} session={session} reduce={reduce === true}/> : null}
    </TooltipContext.Provider>);
}
function TooltipLayer({ tip, open, session, reduce }: {
    tip: Tip;
    open: boolean;
    session: number;
    reduce: boolean;
}) {
    const contentRef = useRef<HTMLDivElement>(null);
    const [size, setSize] = useState<{
        width: number;
        height: number;
        session: number;
    } | null>(null);
    useLayoutEffect(() => {
        const el = contentRef.current;
        if (!el)
            return;
        const rect = el.getBoundingClientRect();
        const next = { width: Math.ceil(rect.width), height: Math.ceil(rect.height), session };
        setSize((prev) => prev && prev.width === next.width && prev.height === next.height && prev.session === next.session ? prev : next);
    }, [tip, session]);
    const measured = size !== null && size.session === session;
    const height = measured ? size.height : 0;
    const center = tip.anchor.left + tip.anchor.width / 2;
    const halfWidth = measured ? size.width / 2 : 0;
    const viewportWidth = typeof document === "undefined" ? Number.POSITIVE_INFINITY : document.documentElement.clientWidth;
    const x = measured
        ? Math.max(VIEWPORT_MARGIN + halfWidth, Math.min(viewportWidth - VIEWPORT_MARGIN - halfWidth, center))
        : center;
    const y = tip.anchor.top - height - GAP;
    const [settledSession, setSettledSession] = useState<number | null>(null);
    useEffect(() => {
        if (!measured)
            return;
        const raf = window.requestAnimationFrame(() => setSettledSession(session));
        return () => window.cancelAnimationFrame(raf);
    }, [measured, session]);
    const position: Transition = reduce || settledSession !== session ? INSTANT : MORPH_SPRING;
    if (typeof document === "undefined")
        return null;
    return artemisCreatePortal(<motion.div key={`${session}:${measured ? 1 : 0}`} aria-hidden="true" className="art:pointer-events-none art:fixed art:top-0 art:left-0 art:z-[2147483647]" initial={{ opacity: 0, x, y: y + 2 }} animate={{ opacity: open && measured ? 1 : 0, x, y }} transition={{ opacity: reduce ? INSTANT : ROOT_FADE, x: position, y: position }}>
      <div style={{ transform: "translateX(-50%)", willChange: "transform" }}>
        <motion.div className="art:relative art:overflow-hidden art:rounded-xl art:border art:border-background/15 art:bg-foreground art:text-background" style={{ transformOrigin: "center bottom", willChange: "width, height, transform" }} initial={{ scale: 1, opacity: 1 }} animate={measured ? { scale: 1, opacity: 1, width: size.width, height: size.height } : { scale: 1, opacity: 1 }} transition={{ width: position, height: position, default: INSTANT }}>
          <div ref={contentRef} className="art:absolute art:top-1/2 art:left-1/2 art:w-max art:max-w-[min(18rem,calc(100vw-24px))] art:-translate-x-1/2 art:-translate-y-1/2 art:px-2 art:py-2 art:text-center art:text-xs">
            <motion.div initial={{ opacity: 0, y: 5 }} animate={open && measured ? { opacity: 1, y: 0 } : { opacity: 0, y: measured ? 3 : 5 }} transition={reduce ? INSTANT : { opacity: TEXT_FADE, y: TEXT_SPRING }}>
              {tip.content}
            </motion.div>
          </div>
        </motion.div>
      </div>
    </motion.div>, document.body);
}
export function ArtemisMorphicTooltip({ content, className, children, }: {
    content: ReactNode;
    className?: string;
    children: ReactNode;
}) {
    const api = useContext(TooltipContext);
    const idRef = useRef(0);
    if (idRef.current === 0)
        idRef.current = nextTriggerId++;
    const ref = useRef<HTMLSpanElement>(null);
    const suppressed = useRef(false);
    const inside = (node: EventTarget | null) => node instanceof Node && Boolean(ref.current?.contains(node));
    const onPointerEnter = (event: PointerEvent<HTMLSpanElement>) => {
        if (event.pointerType !== "mouse" || !api || !ref.current || !inside(event.target))
            return;
        if (suppressed.current)
            return;
        api.show(idRef.current, content, ref.current, OPEN_DELAY);
    };
    const onPointerLeave = (event: PointerEvent<HTMLSpanElement>) => {
        if (event.pointerType !== "mouse" || !api)
            return;
        suppressed.current = false;
        if (ref.current?.contains(document.activeElement) && document.activeElement?.matches(":focus-visible"))
            return;
        api.hide(idRef.current, CLOSE_DELAY);
    };
    const onPointerDown = (event: PointerEvent<HTMLSpanElement>) => {
        if (!api || !inside(event.target))
            return;
        suppressed.current = true;
        api.hide(idRef.current, 0);
    };
    const onFocus = (event: FocusEvent<HTMLSpanElement>) => {
        if (!api || !ref.current || !inside(event.target))
            return;
        const target = event.target as HTMLElement;
        if (!target.matches(":focus-visible"))
            return;
        api.show(idRef.current, content, ref.current, 0);
    };
    const onBlur = (event: FocusEvent<HTMLSpanElement>) => {
        if (!api || !inside(event.target))
            return;
        if (ref.current?.contains(event.relatedTarget as Node | null))
            return;
        if (ref.current?.matches(":hover"))
            return;
        api.hide(idRef.current, 0);
    };
    useEffect(() => {
        const id = idRef.current;
        return () => api?.hide(id, 0);
    }, [api]);
    return (<span ref={ref} className={artemisCx("art:inline-flex", className)} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} onPointerDown={onPointerDown} onFocus={onFocus} onBlur={onBlur}>
      {children}
    </span>);
}

"use client";
// @zeus-internal
import { Archive, Bell, Check, CheckCheck, Clock3, Mail, MailOpen, X } from "lucide-react";
import { AnimatePresence, microtask, motion, useIsPresent, visualElementStore } from "motion/react";
import { type KeyboardEvent as ReactKeyboardEvent, type Ref, type RefObject, useCallback, useEffect, useId, useRef, useState, } from "react";
import { flushSync } from "react-dom";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
import type { NotificationFilter, NotificationItem } from "./data";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./morphic-tooltip";
import { RowMenu } from "./row-menu";
const PANEL_CLIP_OPEN = "inset(0% round 16px)";
const PANEL_CLIP_INITIAL = "inset(0% 0% 92% 92% round 16px)";
const UNDERLINE_SPRING = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 } as const;
const LIST_FADE = { duration: 0.14, ease: ARTEMIS_EASE_OUT } as const;
const EMPTY_FADE = { duration: 0.12, ease: "easeOut" } as const;
const ROW_EXIT = {
    opacity: 0,
    x: 8,
    transition: { opacity: { duration: 0.12, ease: "easeOut" }, x: { duration: 0.15, ease: ARTEMIS_EASE_OUT } },
} as const;
const FOCUS_RING = "art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
type Side = "top" | "bottom";
type Position = {
    left: number;
    top: number;
    origin: number;
    side: Side;
    maxHeight: number;
};
const GAP = 8;
const VIEWPORT_PADDING = 16;
function measurePosition(trigger: HTMLElement, panel: HTMLElement): Position {
    const rect = trigger.getBoundingClientRect();
    const width = panel.offsetWidth;
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
    const natural = Math.min(36 * rem, vh - 2 * rem);
    const left = Math.max(VIEWPORT_PADDING, Math.min(rect.right - width, vw - VIEWPORT_PADDING - width));
    const origin = ((rect.left + rect.width / 2 - left) / width) * 100;
    const below = vh - (rect.bottom + GAP) - VIEWPORT_PADDING;
    const above = rect.top - GAP - VIEWPORT_PADDING;
    if (below < natural && above > below) {
        const height = Math.min(natural, above);
        return { left, top: Math.max(VIEWPORT_PADDING, rect.top - GAP - height), origin, side: "top", maxHeight: above };
    }
    return { left, top: rect.bottom + GAP, origin, side: "bottom", maxHeight: below };
}
function exitClip(origin: number, side: Side) {
    const left = Math.min(92, Math.max(0, origin - 4));
    const [top, bottom] = side === "top" ? [92, 0] : [0, 92];
    return `inset(${top}% ${92 - left}% ${bottom}% ${left}% round 16px)`;
}
type ProjectionProbe = {
    projection?: {
        root?: {
            hasTreeAnimated?: boolean;
        };
    };
};
function projectionTreeHasAnimated(element: Element | null) {
    if (!element)
        return false;
    const store = visualElementStore as unknown as WeakMap<Element, ProjectionProbe>;
    return store.get(element)?.projection?.root?.hasTreeAnimated === true;
}
export type NotificationDropdownProps = {
    items: NotificationItem[];
    filters: NotificationFilter[];
    onReadChange: (item: NotificationItem, read: boolean) => void;
    onMarkAllRead: () => void;
    onSnooze: (item: NotificationItem) => void;
    onArchive: (item: NotificationItem) => void;
    onSelect: (item: NotificationItem) => void;
};
export function NotificationDropdown({ items, filters, onReadChange, onMarkAllRead, onSnooze, onArchive, onSelect, }: NotificationDropdownProps) {
    const id = useId();
    const [open, setOpen] = useState(false);
    const [treeAnimated, setTreeAnimated] = useState(false);
    const triggerRef = useRef<HTMLButtonElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const unread = items.filter((item) => !item.read).length;
    const close = useCallback((returnFocus: boolean) => {
        setOpen(false);
        if (returnFocus)
            triggerRef.current?.focus({ preventScroll: true });
    }, []);
    return (<div ref={wrapperRef} className="art:relative art:inline-flex">
      <ArtemisButton ref={triggerRef} variant="tertiary" className={artemisCx("art:relative art:size-9 art:p-0", FOCUS_RING)} aria-label={`Notifications, ${unread} unread`} id={`${id}-trigger`} aria-haspopup="dialog" aria-expanded={open} aria-controls={open ? `${id}-content` : undefined} onClick={() => {
            if (!open)
                setTreeAnimated(projectionTreeHasAnimated(triggerRef.current));
            setOpen(!open);
        }}>
        <Bell className="art:size-4" aria-hidden="true"/>
        {unread > 0 ? (<span aria-hidden="true" className="art:absolute art:-top-1 art:-right-1 art:flex art:min-w-4 art:items-center art:justify-center art:rounded-full art:bg-primary art:px-1 art:text-xs art:font-medium art:tabular-nums art:text-primary-foreground">
            {unread}
          </span>) : null}
      </ArtemisButton>
      <AnimatePresence>
        {open ? (<Panel key="panel" id={id} treeAnimated={treeAnimated} trigger={triggerRef} wrapper={wrapperRef} items={items} filters={filters} unread={unread} onClose={close} onReadChange={onReadChange} onMarkAllRead={onMarkAllRead} onSnooze={onSnooze} onArchive={onArchive} onSelect={(item) => {
                onSelect(item);
                close(true);
            }}/>) : null}
      </AnimatePresence>
    </div>);
}
type PanelProps = Omit<NotificationDropdownProps, "onSelect"> & {
    id: string;
    treeAnimated: boolean;
    trigger: RefObject<HTMLButtonElement | null>;
    wrapper: RefObject<HTMLDivElement | null>;
    unread: number;
    onClose: (returnFocus: boolean) => void;
    onSelect: (item: NotificationItem) => void;
};
function Panel({ id, treeAnimated, trigger, wrapper, items, filters, unread, onClose, onReadChange, onMarkAllRead, onSnooze, onArchive, onSelect, }: PanelProps) {
    const tabsId = useId();
    const [position, setPosition] = useState<Position | null>(null);
    const [filter, setFilter] = useState("all");
    const [menuContainer, setMenuContainer] = useState<HTMLDivElement | null>(null);
    const floatingRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const tabRefs = useRef<Record<string, HTMLButtonElement | null>>({});
    const pendingFocus = useRef<string | null>(null);
    const tabs: NotificationFilter[] = [{ id: "all", label: "All" }, ...filters];
    const visible = filter === "all" ? items : items.filter((item) => item.category === filter);
    useEffect(() => {
        let active = true;
        const update = () => {
            const anchor = trigger.current;
            const panel = contentRef.current;
            if (active && anchor && panel)
                setPosition(measurePosition(anchor, panel));
        };
        const sizeOf = (width: number, height: number) => `${Math.round(width)}x${Math.round(height)}`;
        let size = contentRef.current ? sizeOf(contentRef.current.offsetWidth, contentRef.current.offsetHeight) : "";
        if (treeAnimated)
            update();
        else {
            microtask.postRender(() => queueMicrotask(() => active && flushSync(update)));
        }
        const observer = new ResizeObserver(([entry]) => {
            const box = entry.borderBoxSize?.[0];
            const next = box ? sizeOf(box.inlineSize, box.blockSize) : sizeOf(entry.contentRect.width, entry.contentRect.height);
            if (next === size)
                return;
            size = next;
            update();
        });
        if (contentRef.current)
            observer.observe(contentRef.current);
        window.addEventListener("resize", update);
        window.addEventListener("scroll", update, true);
        return () => {
            active = false;
            observer.disconnect();
            window.removeEventListener("resize", update);
            window.removeEventListener("scroll", update, true);
        };
    }, [trigger, treeAnimated]);
    const focusedOnOpen = useRef(false);
    useEffect(() => {
        if (!position || focusedOnOpen.current)
            return;
        const raf = requestAnimationFrame(() => {
            focusedOnOpen.current = true;
            tabRefs.current[filter]?.focus({ preventScroll: true });
        });
        return () => cancelAnimationFrame(raf);
    }, [position, filter]);
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key !== "Escape" || event.defaultPrevented)
                return;
            event.preventDefault();
            onClose(true);
        };
        const onPointerDown = (event: PointerEvent) => {
            const target = event.target as Node | null;
            if (!target)
                return;
            if (floatingRef.current?.contains(target) || wrapper.current?.contains(target))
                return;
            onClose(false);
        };
        document.addEventListener("keydown", onKeyDown);
        document.addEventListener("pointerdown", onPointerDown);
        return () => {
            document.removeEventListener("keydown", onKeyDown);
            document.removeEventListener("pointerdown", onPointerDown);
        };
    }, [onClose, wrapper]);
    useEffect(() => {
        const target = pendingFocus.current;
        if (target === null)
            return;
        pendingFocus.current = null;
        requestAnimationFrame(() => {
            const row = target === "" ? null : floatingRef.current?.querySelector<HTMLElement>(`li[data-notification-row="${target}"]`);
            const el = row ? row.querySelector<HTMLElement>("button") : tabRefs.current[filter];
            el?.focus({ preventScroll: true });
        });
    });
    const remove = (item: NotificationItem, action: (item: NotificationItem) => void) => {
        const index = visible.findIndex((entry) => entry.id === item.id);
        const next = visible[index + 1] ?? visible[index - 1];
        pendingFocus.current = next ? next.id : "";
        action(item);
    };
    const onTabKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
        const index = tabs.findIndex((tab) => tab.id === filter);
        let nextIndex = -1;
        if (event.key === "ArrowRight")
            nextIndex = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft")
            nextIndex = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home")
            nextIndex = 0;
        else if (event.key === "End")
